select gv.structure, gv.version, (select coalesce(json_agg(json_build_object('noeud', c.noeud, 'valeur', c.valeur)), '[]') from azimut.cases c where c.grille_id = g.id and c.participant_id = '019e807a-ec7e-721d-bcc5-2915a69eac80' and c.valeur is not null) as cases, (select coalesce(json_agg(json_build_object('noeud', n.noeud, 'axe', n.axe)), '[]') from azimut.non_evaluations n where n.grille_id = g.id and n.participant_id = '019e807a-ec7e-721d-bcc5-2915a69eac80' and n.active) as nes, (select coalesce(json_agg(json_build_object('joker_def', j.joker_def) order by j.horodatage), '[]') from azimut.jokers_poses j where j.grille_id = g.id and j.participant_id = '019e807a-ec7e-721d-bcc5-2915a69eac80' and j.actif) as jokers from azimut.grilles g join azimut.grille_versions gv on gv.grille_id = g.id and gv.version = g.version_saisie where g.id = '019e807a-ec1f-791c-96fa-7ee2192c21ca';
